							aria-label="Enter maximum price"
						/>
						<span className="text-muted-foreground pointer-events-none absolute inset-y-0 inset-s-0 flex items-center justify-center ps-3 text-sm peer-disabled:opacity-50">
							$
						</span>
					</div>
				</div>
			</div>

			{/* Button */}
			<Button className="w-full" variant="outline">
				Show {countItemsInRange(sliderValue[0], sliderValue[1])} items
			</Button>
